package glitch

import data.glitch_lib

# Patterns for cleartext transmission detection
encryption_disabling_attrs := {
    "enableencryption", "enableencryption",
    "requiresecuretransfer", 
    "httpsonly", "enforcehttps",
    "sslrequired", "tlsenabled",
    "requiressl", "usessl",
    "encryptintransit", "encryption",
    "ssl", "tls", "sslmode", "tlsmode",
    "encrypt"
}

# Patterns for cleartext protocols
cleartext_url_prefixes := {"http://", "ftp://", "telnet://", "smtp://", "ldap://"}
cleartext_protocols := {"http", "ftp", "telnet", "smtp", "ldap", "tcp", "udp", "plaintext"}

# Patterns for weak TLS versions
weak_tls_versions := {"1.0", "1.1", "tls1.0", "tls1.1"}

# Check if value indicates encryption is disabled
is_encryption_disabled(value) {
    value.ir_type == "Boolean"
    value.value == false
} else {
    value.ir_type == "String"
    lower(value.value) == "false"
} else {
    value.ir_type == "String"
    lower(value.value) == "disabled"
} else {
    value.ir_type == "String"
    lower(value.value) == "disable"
} else {
    value.ir_type == "String"
    lower(value.value) == "off"
} else {
    value.ir_type == "String"
    lower(value.value) == "none"
} else {
    value.ir_type == "String"
    lower(value.value) == "optional"
} else {
    value.ir_type == "String"
    lower(value.value) == "allow"
} else {
    value.ir_type == "String"
    lower(value.value) == "prefer"
} else {
    value.ir_type == "Integer"
    value.value == 0
}

# Check if value indicates weak/no encryption
is_weak_encryption(value) {
    value.ir_type == "String"
    lower(value.value) == lower(weak_tls_versions[_])
}

# Check if value indicates cleartext protocol
has_cleartext_protocol(value) {
    value.ir_type == "String"
    protocol := lower(value.value)
    protocol == cleartext_protocols[_]
}

# Check if URL starts with cleartext prefix
has_cleartext_url(value) {
    value.ir_type == "String"
    url := lower(value.value)
    prefix := cleartext_url_prefixes[_]
    startswith(url, prefix)
}

# Check attribute name indicates encryption control
is_encryption_attribute(name) {
    lower_name := lower(name)
    lower_name == encryption_disabling_attrs[_]
} else {
    lower_name := lower(name)
    contains(lower_name, "encryption")
} else {
    lower_name := lower(name)
    contains(lower_name, "ssl")
} else {
    lower_name := lower(name)
    contains(lower_name, "tls")
} else {
    lower_name := lower(name)
    contains(lower_name, "protocol")
} else {
    lower_name := lower(name)
    contains(lower_name, "scheme")
} else {
    lower_name := lower(name)
    contains(lower_name, "url")
} else {
    lower_name := lower(name)
    contains(lower_name, "endpoint")
} else {
    lower_name := lower(name)
    contains(lower_name, "connection")
}

# Check for plaintext security protocol settings
is_plaintext_security(value) {
    value.ir_type == "String"
    lower(value.value) == "plaintext"
}

# Detect CWE-319: Cleartext Transmission of Sensitive Information
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    # Case 1: Encryption explicitly disabled
    is_encryption_attribute(attr.name)
    is_encryption_disabled(attr.value)

    result := {
        "type": "sec_https",
        "element": attr,
        "path": parent.path,
        "description": "Cleartext transmission of sensitive information - Encryption for data transmission is disabled, allowing sensitive data to travel unencrypted. (CWE-319)"
    }
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    # Case 2: Weak TLS version configured
    is_encryption_attribute(attr.name)
    is_weak_encryption(attr.value)

    result := {
        "type": "sec_https",
        "element": attr,
        "path": parent.path,
        "description": "Cleartext transmission of sensitive information - Weak or deprecated TLS version configured, providing insufficient encryption strength. (CWE-319)"
    }
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    # Case 3: Cleartext protocol explicitly set
    is_encryption_attribute(attr.name)
    has_cleartext_protocol(attr.value)

    result := {
        "type": "sec_https",
        "element": attr,
        "path": parent.path,
        "description": "Cleartext transmission of sensitive information - Cleartext protocol configured for data transmission without encryption. (CWE-319)"
    }
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    # Case 4: Cleartext URL/endpoint configured
    has_cleartext_url(attr.value)

    result := {
        "type": "sec_https",
        "element": attr,
        "path": parent.path,
        "description": "Cleartext transmission of sensitive information - URL configured with unencrypted HTTP or other cleartext protocol. (CWE-319)"
    }
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    # Case 5: Plaintext security protocol (e.g., Kafka PLAINTEXT)
    is_plaintext_security(attr.value)

    result := {
        "type": "sec_https",
        "element": attr,
        "path": parent.path,
        "description": "Cleartext transmission of sensitive information - Plaintext security protocol configured, disabling encryption for data transmission. (CWE-319)"
    }
}

package glitch

import data.glitch_lib

# Patterns for cleartext transmission detection
cleartext_url_prefixes := {"http://", "ftp://", "telnet://", "smtp://", "ldap://"}
cleartext_protocols := {"http", "ftp", "telnet", "smtp", "ldap", "tcp", "udp", "plaintext", "no"}
weak_tls_versions := {"1.0", "1.1", "tls1.0", "tls1.1"}

# Recursively check if any string in expression has cleartext URL prefix
has_cleartext_url_in_expr(expr) {
    expr.ir_type == "String"
    url := lower(expr.value)
    prefix := cleartext_url_prefixes[_]
    startswith(url, prefix)
} else {
    expr.ir_type == "Sum"
    has_cleartext_url_in_expr(expr.left)
} else {
    expr.ir_type == "Sum"
    has_cleartext_url_in_expr(expr.right)
} else {
    expr.ir_type == "Hash"
    entry := expr.value[_]
    has_cleartext_url_in_expr(entry.value)
} else {
    expr.ir_type == "Array"
    item := expr.value[_]
    has_cleartext_url_in_expr(item)
} else {
    expr.ir_type in ["MethodCall", "FunctionCall"]
    arg := expr.args[_]
    has_cleartext_url_in_expr(arg)
} else {
    expr.ir_type == "BlockExpr"
    stmt := expr.statements[_]
    has_cleartext_url_in_expr(stmt)
}

# Recursively check if any string in expression indicates cleartext protocol
has_cleartext_protocol_in_expr(expr) {
    expr.ir_type == "String"
    protocol := lower(expr.value)
    protocol == cleartext_protocols[_]
} else {
    expr.ir_type == "Sum"
    has_cleartext_protocol_in_expr(expr.left)
} else {
    expr.ir_type == "Sum"
    has_cleartext_protocol_in_expr(expr.right)
} else {
    expr.ir_type == "Hash"
    entry := expr.value[_]
    has_cleartext_protocol_in_expr(entry.value)
} else {
    expr.ir_type == "Array"
    item := expr.value[_]
    has_cleartext_protocol_in_expr(item)
}

# Recursively check if any string in expression indicates disabled encryption
has_disabled_encryption_in_expr(expr) {
    expr.ir_type == "Boolean"
    expr.value == false
} else {
    expr.ir_type == "String"
    val := lower(expr.value)
    val in {"false", "disabled", "disable", "off", "none", "optional", "allow", "prefer", "no"}
} else {
    expr.ir_type == "Integer"
    expr.value == 0
} else {
    expr.ir_type == "Sum"
    has_disabled_encryption_in_expr(expr.left)
} else {
    expr.ir_type == "Sum"
    has_disabled_encryption_in_expr(expr.right)
}

# Recursively check if any string in expression indicates weak TLS
has_weak_tls_in_expr(expr) {
    expr.ir_type == "String"
    ver := lower(expr.value)
    ver == weak_tls_versions[_]
} else {
    expr.ir_type == "Float"
    expr.value == 1.0
} else {
    expr.ir_type == "Float"
    expr.value == 1.1
} else {
    expr.ir_type == "Sum"
    has_weak_tls_in_expr(expr.left)
} else {
    expr.ir_type == "Sum"
    has_weak_tls_in_expr(expr.right)
}

# Check if attribute name indicates certificate/encryption validation
is_cert_validation_attr(name) {
    lower_name := lower(name)
    contains(lower_name, "validate_cert")
} else {
    lower_name := lower(name)
    contains(lower_name, "verify_cert")
} else {
    lower_name := lower(name)
    contains(lower_name, "verify_ssl")
} else {
    lower_name := lower(name)
    contains(lower_name, "ssl_verify")
}

# Check if attribute name indicates encryption control
is_encryption_control_attr(name) {
    lower_name := lower(name)
    contains(lower_name, "encryption")
} else {
    lower_name := lower(name)
    contains(lower_name, "ssl")
} else {
    lower_name := lower(name)
    contains(lower_name, "tls")
}

# Check if attribute name indicates protocol/scheme/URL
is_protocol_attr(name) {
    lower_name := lower(name)
    contains(lower_name, "protocol")
} else {
    lower_name := lower(name)
    contains(lower_name, "scheme")
} else {
    lower_name := lower(name)
    contains(lower_name, "url")
} else {
    lower_name := lower(name)
    contains(lower_name, "source")
} else {
    lower_name := lower(name)
    contains(lower_name, "endpoint")
} else {
    lower_name := lower(name)
    contains(lower_name, "address")
}

# Recursively traverse attributes in Hash values
all_nested_attributes(node) = attrs {
    attrs := {attr |
        walk(node, [path, n])
        n.ir_type == "Attribute"
    }
}

# Get all variables from UnitBlock
all_block_variables(block) = vars {
    vars := {v |
        walk(block, [path, v])
        v.ir_type == "Variable"
    }
}

# Case 1: Certificate validation explicitly disabled
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]
    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    is_cert_validation_attr(attr.name)
    has_disabled_encryption_in_expr(attr.value)

    result := {
        "type": "sec_https",
        "element": attr,
        "path": parent.path,
        "description": "Cleartext transmission of sensitive information - Certificate validation is disabled, allowing unencrypted or unverified connections. (CWE-319)"
    }
}

# Case 2: Encryption setting explicitly disabled
Glitch_Analysis[result] {
