        "element": attr,
        "path": parent.path,
        "description": "Cleartext transmission of sensitive information - Encryption for data transmission is disabled, allowing sensitive data to travel unencrypted. (CWE-319)"
    }
}

# Case 3: Weak TLS version configured
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]
    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    is_encryption_control_attr(attr.name)
    has_weak_tls_in_expr(attr.value)

    result := {
        "type": "sec_https",
        "element": attr,
        "path": parent.path,
        "description": "Cleartext transmission of sensitive information - Weak or deprecated TLS version configured, providing insufficient encryption strength. (CWE-319)"
    }
}

# Case 4: Cleartext protocol in attributes
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]
    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    is_protocol_attr(attr.name)
    has_cleartext_protocol_in_expr(attr.value)

    result := {
        "type": "sec_https",
        "element": attr,
        "path": parent.path,
        "description": "Cleartext transmission of sensitive information - Cleartext protocol configured for data transmission without encryption. (CWE-319)"
    }
}

# Case 5: Cleartext URL in any attribute
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]
    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    has_cleartext_url_in_expr(attr.value)

    result := {
        "type": "sec_https",
        "element": attr,
        "path": parent.path,
        "description": "Cleartext transmission of sensitive information - URL configured with unencrypted HTTP or other cleartext protocol. (CWE-319)"
    }
}

# Case 6: Variables with cleartext URLs or protocols ( Ansible vars, etc.)
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    vars := all_block_variables(parent)
    v := vars[_]

    is_protocol_attr(v.name)
    has_cleartext_protocol_in_expr(v.value)

    result := {
        "type": "sec_https",
        "element": v,
        "path": parent.path,
        "description": "Cleartext transmission of sensitive information - Cleartext protocol configured for data transmission without encryption. (CWE-319)"
    }
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    vars := all_block_variables(parent)
    v := vars[_]

    has_cleartext_url_in_expr(v.value)

    result := {
        "type": "sec_https",
        "element": v,
        "path": parent.path,
        "description": "Cleartext transmission of sensitive information - URL configured with unencrypted HTTP or other cleartext protocol. (CWE-319)"
    }
}

# Case 7: Nested Hash attributes with protocol settings
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    vars := all_block_variables(parent)
    v := vars[_]
    v.value.ir_type == "Hash"

    entry := v.value.value[_]
    key_str := entry.key.value
    is_protocol_attr(key_str)
    has_cleartext_protocol_in_expr(entry.value)

    result := {
        "type": "sec_https",
        "element": v,
        "path": parent.path,
        "description": "Cleartext transmission of sensitive information - Cleartext protocol configured for data transmission without encryption. (CWE-319)"
    }
}

